usageExamples.code:
let maps = recipemaps(<machine>)
if (maps.status == "matches") {
  print(maps.current, maps.available)
}

let details = recipe(<selected_reference>)
if (details.status == "matches" and details.coverageComplete and len(details.recipes) == 1) {
  let chosen = details.recipes[0]
  print(chosen.duration, chosen.eut, chosen.itemInputs)
}

entries.insert:
every redstone rising from "sensor" north side {
  output 15 redstone level to "emit" east side
}
every redstone falling from "sensor" north side {
  output 0 redstone level to "emit" east side
}

let portInput = label("sensor").side("north")
if (portInput.redstoneAvailable()) {
  let signalLevel = portInput.redstone()
  output (signalLevel) redstone level to "emit" east side
}

let reading = label("source").contents()
for group in reading {
  print(group.id, group.metadata, group.total)
  for location in group.locations {
    print(location.x, location.y, location.z, location.slot, location.amount)
  }
}

let reading = label("<source>").contents()
for group in reading {
  let key = group.item
  if (key.nbttype() == "compound") {
    print(key.nbtkeys())
  }
  let heatType = key.nbttype("/heat")
  if (heatType == "byte" or heatType == "short" or heatType == "int" or heatType == "long") {
    print("raw heat", key.nbtinteger("/heat"))
  }
}

let baseline = label("source").contents()
every 20 ticks {
  let current = label("source").contents()
  if (len(baseline) > 0 and len(current) > 0) {
    print("first group item changed", current[0].item != baseline[0].item)
  }
}

state runs = 0
